fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("fixtures")
}

fn valid_fixture(name: &str) -> PathBuf {
    fixtures_dir().join("valid").join(name)
}

fn malformed_fixture(name: &str) -> PathBuf {
    fixtures_dir().join("malformed").join(name)
}

fn dup_fixture(name: &str) -> PathBuf {
    fixtures_dir().join("duplicates").join(name)
}

fn eco_file_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("resources/pgn-extract/eco.pgn")
}

async fn resolve_engine() -> (EngineExecutable, EngineCapabilities) {
    let result = startup_check(&SidecarLocation::dev_default()).await.expect(
        "the real, checksum-pinned sidecar must resolve and pass its startup self-test - if \
             this fails, `src-tauri/binaries/pgn-extract-x86_64-pc-windows-msvc.exe` is missing \
             or does not match the pinned checksum",
    );
    (result.engine, result.capabilities)
}

fn read_to_string(path: &Path) -> String {
    std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()))
}

/// Whitespace-tokenized exact-match check. pgn-extract wraps long movetext
/// lines at word boundaries, so any assertion on a *multi-token* substring
/// (e.g. an entire variation) is fragile against exactly where a line wraps.
/// A wrap is, by construction, only ever substituted for a space, so
/// splitting on ANY whitespace (including the inserted newline) and matching
/// one whole token is robust regardless of wrapping. Distinguishes "$1" from
/// "$10" (a plain `contains` would wrongly find "$1" inside "$10").
fn has_token(text: &str, token: &str) -> bool {
    text.split_whitespace().any(|t| t == token)
}

fn no_cleanup() -> CleanupOptions {
    CleanupOptions {
        remove_comments: false,
        remove_variations: false,
        remove_nags: false,
        remove_move_numbers: false,
        remove_results: false,
        remove_tags: vec![],
        reject_bad_results: false,
        fix_result_tags: false,
    }
}

/// A generic, minimal `JobSpec` builder: `Process` mode, inputs ordered by
/// their position in `inputs` (input order is duplicate-retention priority,
/// architecture.md §10.7), `Fail` conflict policy, no cleanup/filters/ECO,
/// no duplicate handling, no log/manifest artifacts. Individual tests mutate
/// exactly the fields their scenario cares about, matching
/// `duplicate_integration.rs`'s `dedup_spec` pattern.
fn base_spec(inputs: Vec<PathBuf>, destination_dir: PathBuf, base_name: &str) -> JobSpec {
    JobSpec {
        schema_version: CURRENT_SCHEMA_VERSION,
        id: Uuid::new_v4(),
        name: "phase4-integration-test".to_string(),
        inputs: inputs
            .into_iter()
            .enumerate()
            .map(|(i, path)| InputFile {
                display_name: path.display().to_string(),
                path,
                priority: i as u32,
            })
            .collect(),
        output: OutputPlan {
            directory: destination_dir,
            base_name: base_name.to_string(),
            unique_games: true,
            duplicate_games: DuplicateOutput::None,
            log_file: false,
            manifest: false,
            always_create_audit: false,
            conflict_policy: ConflictPolicy::Fail,
            confirmed_replace: false,
        },
        operations: OperationPlan {
            mode: JobMode::Process,
            duplicates: DuplicatePolicy::None,
            cleanup: no_cleanup(),
            broken: BrokenOutput::Discard,
            eco: EcoOptions { enabled: false },
            output_notation: OutputNotation::San,
            check_file: None,
        },
        filters: FilterPlan {
            tag_rules: vec![],
            move_bounds: None,
            checkmate_only: false,
            setup_policy: SetupPolicy::Any,
            fen_pattern: None,
            textual_variations: vec![],
            advanced_args: vec![],
        },
        runtime: RuntimeOptions {
            use_external_duplicate_table: false,
            count_output_games: true,
        },
    }
}

// ===========================================================================
// A. Cleanup / validation / ECO golden output verification
// ===========================================================================

/// `-C` alone: comments removed, variations AND NAGs untouched. Combines
/// `long-comment.pgn` (a comment, no variations/NAGs) with
/// `variations-and-nags.pgn` (variations and NAGs, no comment) in one job so
/// a single run exercises all three annotation kinds at once.
#[tokio::test]
async fn cleanup_remove_comments_alone_strips_comments_but_keeps_variations_and_nags() {
    let (engine, caps) = resolve_engine().await;
    let inputs = vec![
        valid_fixture("long-comment.pgn"),
        valid_fixture("variations-and-nags.pgn"),
    ];
    let dest = tempfile::tempdir().unwrap();
    let jobs_root = tempfile::tempdir().unwrap();
    let eco_file = eco_file_path();
    let mut spec = base_spec(inputs, dest.path().to_path_buf(), "cleanup-c-only");
    spec.operations.cleanup.remove_comments = true;

    let state = AppState::new();
    let ctx = RunJobContext {
        caps: &caps,
        engine: &engine,
        jobs_root: jobs_root.path(),
        eco_file: &eco_file,
    };
    let result = run_job(spec, &ctx, &state, &NullEventSink).await.unwrap();
    assert_eq!(result.status, JobStatus::Succeeded, "{:?}", result.error);

    let output_path = dest.path().join("cleanup-c-only.pgn");
    assert_eq!(count_games_in_file(&output_path).unwrap(), 2);
    let text = read_to_string(&output_path);
    assert!(!has_token(&text, "{"), "the comment marker must be gone");
    assert!(!has_token(&text, "}"), "the comment marker must be gone");
    assert!(
        has_token(&text, "(2."),
        "the variation must survive -C alone"
    );
    assert!(
        has_token(&text, "$1") && has_token(&text, "$6") && has_token(&text, "$10"),
        "NAGs must survive -C alone"
    );
}

