/// `--noresults`: the movetext's own trailing result token is removed, but
/// the `Result` header TAG is unaffected - task instruction: "confirm this
/// and make sure the UI wording matches reality" (it already does; see
/// `CleanupSection.tsx`'s "Remove result markers from the movetext" help
/// text). Uses `multi-game-results.pgn` (three games: "1/2-1/2", "0-1",
/// "*") to cover every result kind at once.
#[tokio::test]
async fn noresults_strips_movetext_result_token_but_keeps_result_tag() {
    let (engine, caps) = resolve_engine().await;
    let inputs = vec![valid_fixture("multi-game-results.pgn")];
    let dest = tempfile::tempdir().unwrap();
    let jobs_root = tempfile::tempdir().unwrap();
    let eco_file = eco_file_path();
    let mut spec = base_spec(inputs, dest.path().to_path_buf(), "cleanup-noresults");
    spec.operations.cleanup.remove_results = true;

    let state = AppState::new();
    let ctx = RunJobContext {
        caps: &caps,
        engine: &engine,
        jobs_root: jobs_root.path(),
        eco_file: &eco_file,
    };
    let result = run_job(spec, &ctx, &state, &NullEventSink).await.unwrap();
    assert_eq!(result.status, JobStatus::Succeeded, "{:?}", result.error);

    let text = read_to_string(&dest.path().join("cleanup-noresults.pgn"));
    assert_eq!(
        count_games_in_file(&dest.path().join("cleanup-noresults.pgn")).unwrap(),
        3
    );
    // Every Result TAG survives, verbatim, for all three result kinds.
    assert!(text.contains("[Result \"1/2-1/2\"]"));
    assert!(text.contains("[Result \"0-1\"]"));
    assert!(text.contains("[Result \"*\"]"));
    // No bare (unquoted, movetext-only) result token remains anywhere. A
    // plain `contains` on the bare strings would also match nothing extra
    // here since the tag's own value is always quoted (`"1/2-1/2"`, never a
    // bare `1/2-1/2` token) - `has_token` still makes that non-overlap
    // explicit rather than incidental.
    assert!(!has_token(&text, "1/2-1/2"));
    assert!(!has_token(&text, "0-1"));
    assert!(!has_token(&text, "*"));
}

