/// **Critical regression guard.** Calls `compile()` directly (pure, no
/// engine run needed) and asserts the ECO flag is emitted as exactly one
/// attached token `-e<path>`, and that a bare, unattached `-e` token never
/// appears at all. DECISIONS-LEDGER.md D-007 V-4: the separated form is a
/// silent data-loss hazard. This must fail if `command_compiler.rs`'s
/// `attached_flag` helper is ever changed to push `-e` and the path as two
/// separate `OsString`s.
#[tokio::test]
async fn eco_attached_form_is_the_only_form_the_compiler_ever_emits() {
    let (engine, caps) = resolve_engine().await;
    let dest = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let eco_file = eco_file_path();
    let mut spec = base_spec(
        vec![valid_fixture("single-game.pgn")],
        dest.path().to_path_buf(),
        "eco-argv-guard",
    );
    spec.operations.eco.enabled = true;
    let layout = CompileLayout {
        engine: engine.clone(),
        workspace_root: workspace.path().to_path_buf(),
        eco_file: eco_file.clone(),
        destination_dir: dest.path().to_path_buf(),
    };
    let compiled = compile(&spec, &caps, &layout).expect("a minimal ECO-enabled spec must compile");

    let mut expected_attached = OsString::from("-e");
    expected_attached.push(eco_file.as_os_str());
    assert!(
        compiled.args.contains(&expected_attached),
        "the compiler must emit the ECO flag as one attached token \"-e<path>\"; got {:?}",
        compiled.args
    );
    assert!(
        !compiled.args.iter().any(|a| a == "-e"),
        "a bare, unattached \"-e\" token must never appear in the compiled argv - \
         DECISIONS-LEDGER.md D-007 V-4: the separated form fails/corrupts silently. Got {:?}",
        compiled.args
    );
}

/// **Empirical proof of why the previous test matters.** Deliberately
/// bypasses BOTH the command compiler AND this crate's own `pub(crate)`
/// `engine::process` spawn helpers: hand-builds the exact argv the compiler
/// would emit if `attached_flag` ever regressed to the separated form, and
/// spawns the real pinned sidecar directly. Phrased as "not the correct
/// result" rather than pinned to one exact exit code - see this file's
/// module doc comment, finding 3.
#[tokio::test]
async fn eco_separated_form_is_catastrophic_empirical_proof() {
    let (engine, _caps) = resolve_engine().await;
    let workdir = tempfile::tempdir().unwrap();
    let input_path = workdir.path().join("input.pgn");
    std::fs::copy(valid_fixture("single-game.pgn"), &input_path).unwrap();
    let eco_file = eco_file_path();

    // Baseline, in the exact same fresh workspace: the correct, attached
    // form the real compiler emits.
    let attached_output_path = workdir.path().join("attached-out.pgn");
    let mut attached_flag = OsString::from("-e");
    attached_flag.push(&eco_file);
    let mut attached_out_flag = OsString::from("-o");
    attached_out_flag.push(&attached_output_path);
    let attached_run = std::process::Command::new(engine.path())
        .current_dir(workdir.path())
        .arg("-s")
        .arg("--summary")
        .arg(attached_flag)
        .arg(attached_out_flag)
        .arg(&input_path)
        .output()
        .expect("the real sidecar must spawn");
    assert_eq!(
        attached_run.status.code(),
        Some(0),
        "the attached-form baseline itself must succeed"
    );
    assert_eq!(count_games_in_file(&attached_output_path).unwrap_or(0), 1);
    assert!(read_to_string(&attached_output_path).contains("[ECO \"C53\"]"));

    // The dangerous separated form: "-e" and the path as two independent
    // argv elements, exactly what would ship if `attached_flag` regressed.
    let separated_output_path = workdir.path().join("separated-out.pgn");
    let mut separated_out_flag = OsString::from("-o");
    separated_out_flag.push(&separated_output_path);
    let separated_run = std::process::Command::new(engine.path())
        .current_dir(workdir.path())
        .arg("-s")
        .arg("--summary")
        .arg(separated_out_flag)
        .arg("-e")
        .arg(&eco_file)
        .arg(&input_path)
        .output()
        .expect("the real sidecar must spawn");

    let separated_games = if separated_output_path.exists() {
        count_games_in_file(&separated_output_path).unwrap_or(0)
    } else {
        0
    };
    let separated_looks_correct = separated_run.status.code() == Some(0)
        && separated_games == 1
        && std::fs::read_to_string(&separated_output_path)
            .map(|t| t.contains("[ECO \"C53\"]"))
            .unwrap_or(false);
    assert!(
        !separated_looks_correct,
        "the separated -e form must NOT silently reproduce the correct, attached-form result \
         (DECISIONS-LEDGER.md D-007 V-4); got exit {:?}, {separated_games} game(s), correct \
         content: {}",
        separated_run.status.code(),
        std::fs::read_to_string(&separated_output_path)
            .map(|t| t.contains("[ECO \"C53\"]"))
            .unwrap_or(false)
    );
}

