    // presets.ts "mergeSafely": { ...defaultOperationPlan(), mode: "process",
    // duplicates: "none" } - base_spec's own defaults already match every
    // other field (no cleanup, San, ECO off, Discard broken, no check file).
    assert_eq!(spec.operations.mode, JobMode::Process);
    assert_eq!(spec.operations.duplicates, DuplicatePolicy::None);
    assert_eq!(spec.operations.cleanup, no_cleanup());
    assert_eq!(spec.output.duplicate_games, DuplicateOutput::None);
    assert!(spec.output.unique_games);

    let state = AppState::new();
    let ctx = RunJobContext {
        caps: &caps,
        engine: &engine,
        jobs_root: jobs_root.path(),
        eco_file: &eco_file,
    };
