    let mut spec = base_spec(inputs, dest.path().to_path_buf(), "preset-new-vs-master");
    // presets.ts "newGamesAgainstMaster": duplicates: "suppressKeepFirst".
    // checkFile is deliberately never part of a preset's own effect (see
    // presets.ts's own doc comment) - the user chooses it separately, which
    // this test reproduces by setting it explicitly after the "preset".
    spec.operations.duplicates = DuplicatePolicy::SuppressKeepFirst;
    spec.operations.check_file = Some(master.clone());
    assert_eq!(
        spec.operations.duplicates,
        DuplicatePolicy::SuppressKeepFirst
    );
    assert_eq!(spec.operations.check_file, Some(master));

    let state = AppState::new();
    let ctx = RunJobContext {
        caps: &caps,
        engine: &engine,
        jobs_root: jobs_root.path(),
        eco_file: &eco_file,
    };
